<script module>  export const manifiesto = {    id: 'caja',    nombre: 'Caja',    icono: 'wallet',    grupo: 'negocio',    orden: 5,    tablas: { arqueos: '++id, fecha', movCaja: '++id, fecha, tipo' }  };</script><script>  import { onMount } from 'svelte';  import { listar, leerConfig } from '../../core/db.js';  import { bus } from '../../core/bus.js';  import { avisar } from '../../core/state.svelte.js';  import { n, m, fmt, fmtFH, saldoCaja, movimientosCaja } from '../../core/util.js';  import { toNumber, sum, sumWhere } from '../../core/Money.js';  import { CajaService } from '../../services/CajaService.js';  import { obtenerPeriodosCerrados } from '../../core/periodos.js';  import Icono from '../../core/Icono.svelte';  let cfg = $state({});  let capital = $state([]);  let ventas = $state([]);  let compras = $state([]);  let retiros = $state([]);  let movCaja = $state([]);  let arqueos = $state([]);  let arqueoForm = $state({ monto: '', nota: '' });  let paginaMovs = $state(1);  let procesando = $state(false);  let periodosCerrados = $state([]);  const itemsPorPagina = 20;  let saldo = $derived(saldoCaja({ cfg, capital, ventas, compras, retiros, movCaja }));  let aportesTotal = $derived(toNumber(sum(capital, 'monto')));  let ventasTotal = $derived(toNumber(sumWhere(ventas, v => !v.anulada, 'total')));  let comprasTotal = $derived(toNumber(sumWhere(compras, c => !c.anulada, 'total')));  let retirosTotal = $derived(toNumber(sum(retiros, 'monto')));  let arqueoNeto = $derived(toNumber(sumWhere(movCaja, mv => mv.concepto && mv.concepto.toLowerCase().includes('arqueo'), mv => mv.tipo === 'ingreso' ? mv.monto : -mv.monto)));  let movs = $derived(movimientosCaja({ cfg, capital, ventas, compras, retiros, movCaja }));  let movsPaginados = $derived(movs.slice((paginaMovs - 1) * itemsPorPagina, paginaMovs * itemsPorPagina));  let totalPaginasMovs = $derived(Math.max(1, Math.ceil(movs.length / itemsPorPagina)));  let arqueoPreview = $derived((() => {    if (arqueoForm.monto === '' || arqueoForm.monto === null || arqueoForm.monto === undefined) return null;    const monto = n(arqueoForm.monto);    const sys = saldo;    const diff = monto - sys;    const tipo = Math.abs(diff) < 0.01 ? 'cuadre' : (diff > 0 ? 'sobrante' : 'faltante');    return { fisico: monto, sistema: sys, diff: Math.abs(diff), tipo };  })());  async function recargar() {    [capital, ventas, compras, retiros, movCaja, arqueos] = await Promise.all([      listar('capital'), listar('ventas'), listar('compras'), listar('retiros'), listar('movCaja'), listar('arqueos')    ]);    cfg = await leerConfig('cfg') || { capitalInicial: 0 };    periodosCerrados = await obtenerPeriodosCerrados();  }  function esCerrado(fechaIso) {    const f = new Date(fechaIso);    return periodosCerrados.some(p => new Date(p.inicio) <= f && f <= new Date(p.fin));  }  onMount(() => {    recargar();    const off = bus.on('recargar', recargar);    return () => off();  });  async function registrarArqueo() {    if (procesando) return;    const monto = n(arqueoForm.monto);    if (monto < 0 || arqueoForm.monto === '') return avisar('Monto invalido', 'bad');    procesando = true;    try {      const { diff } = await CajaService.registrarArqueo({        montoFisico: monto, saldoSistema: saldo, nota: arqueoForm.nota      });      arqueoForm = { monto: '', nota: '' };      await recargar();      bus.emit('recargar');      if (Math.abs(diff) < 0.01) {        avisar('Cuadre perfecto');      } else {        avisar((diff > 0 ? 'Sobrante ' : 'Faltante ') + fmt(Math.abs(diff)), diff > 0 ? 'warn' : 'bad');      }    } catch (e) {      avisar(e.message, 'bad');    } finally { procesando = false; }  }</script><div class='modulo'>  <!-- Saldo principal -->  <div class='{saldo < 0 ? 'bg-gradient-to-br from-danger to-[#7f1d1d]' : 'bg-gradient-to-br from-primary to-[#1e3a8a]'} text-white rounded-[var(--radius-lg)] p-5 text-center mb-3 shadow-[var(--color-shadow)] relative overflow-hidden'>    <div class='absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -translate-y-1/2 translate-x-1/2'></div>    <div class='relative'>      <div class='flex items-center justify-center gap-1.5 text-xs opacity-90 mb-1'>        <Icono nombre='wallet' size={14} color='#fff' />        Saldo en Caja      </div>      <div class='text-3xl font-extrabold my-0.5'>{fmt(saldo)}</div>      {#if saldo < 0}<div class='text-xs opacity-85'>Caja en negativo</div>{/if}    </div>  </div>  <!-- Desglose visual -->  <div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='chart' size={18} />      Desglose    </div>    <div class='space-y-0'>      <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border text-sm'>        <div class='flex items-center gap-2'>          <div class='w-2 h-2 rounded-full bg-success'></div>          <span>Capital inicial</span>        </div>        <span class='text-success font-bold'>+{fmt(cfg.capitalInicial || 0)}</span>      </div>      <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border text-sm'>        <div class='flex items-center gap-2'>          <div class='w-2 h-2 rounded-full bg-success'></div>          <span>Aportes</span>        </div>        <span class='text-success font-bold'>+{fmt(aportesTotal)}</span>      </div>      <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border text-sm'>        <div class='flex items-center gap-2'>          <div class='w-2 h-2 rounded-full bg-success'></div>          <span>Ventas contado</span>        </div>        <span class='text-success font-bold'>+{fmt(ventasTotal)}</span>      </div>      <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border text-sm'>        <div class='flex items-center gap-2'>          <div class='w-2 h-2 rounded-full bg-danger'></div>          <span>Compras</span>        </div>        <span class='text-danger font-bold'>-{fmt(comprasTotal)}</span>      </div>      <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border text-sm'>        <div class='flex items-center gap-2'>          <div class='w-2 h-2 rounded-full bg-danger'></div>          <span>Retiros</span>        </div>        <span class='text-danger font-bold'>-{fmt(retirosTotal)}</span>      </div>      <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border text-sm'>        <div class='flex items-center gap-2'>          <div class='w-2 h-2 rounded-full {arqueoNeto >= 0 ? 'bg-success' : 'bg-danger'}'></div>          <span>Ajustes arqueo</span>        </div>        <span class='{arqueoNeto >= 0 ? 'text-success' : 'text-danger'} font-bold'>{arqueoNeto >= 0 ? '+' : ''}{fmt(arqueoNeto)}</span>      </div>      <div class='flex justify-between items-center gap-2 py-3 mt-1 bg-primary/5 rounded-xl px-3'>        <span class='font-extrabold text-sm'>= SALDO</span>        <span class='text-primary font-extrabold text-base'>{fmt(saldo)}</span>      </div>    </div>  </div>  <!-- Arqueo -->  <div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)] mb-3'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='search' size={18} />      Arqueo de Caja    </div>    <div class='bg-primary/10 border-l-4 border-primary rounded-[var(--radius-md)] p-3 mb-3 text-sm text-primary'>      Cuenta el dinero fisico y escribe lo que tienes. Si es MENOR que el sistema = faltante; si es MAYOR = sobrante.    </div>    <div class='flex justify-between items-center gap-2 py-1 text-sm mb-2 bg-background rounded-lg px-3'>      <span class='text-muted'>El sistema dice:</span>      <b class='text-primary text-base'>{fmt(saldo)}</b>    </div>    <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='number' inputmode='decimal' step='0.01' placeholder='Monto que contaste fisicamente' bind:value={arqueoForm.monto} />    {#if arqueoPreview}      <div class='rounded-[var(--radius-md)] p-3 mb-2 font-extrabold text-sm {arqueoPreview.tipo === 'cuadre' ? 'bg-success/10 text-success' : arqueoPreview.tipo === 'sobrante' ? 'bg-warning/10 text-warning' : 'bg-danger/10 text-danger'}'>        Tu cuentas: {fmt(arqueoPreview.fisico)} · Diferencia:        {#if arqueoPreview.tipo === 'cuadre'}Cuadre perfecto ✓        {:else if arqueoPreview.tipo === 'sobrante'}SOBRANTE +{fmt(arqueoPreview.diff)}        {:else}FALTANTE -{fmt(arqueoPreview.diff)}{/if}      </div>    {/if}    <input class='w-full px-3.5 py-3 border border-border rounded-[var(--radius-md)] bg-card text-text text-base outline-none focus:border-primary focus:shadow-[0_0_0_3px_rgba(33,150,243,0.15)] mb-2' type='text' placeholder='Nota (opcional)' bind:value={arqueoForm.nota} />    <button class='w-full py-3 rounded-[var(--radius-md)] bg-primary text-white font-extrabold text-sm active:scale-[0.97] transition-transform disabled:opacity-50' onclick={registrarArqueo} disabled={procesando}>      <Icono nombre='check' size={16} color='#fff' />      {procesando ? 'Procesando...' : 'Registrar Arqueo'}    </button>  </div>  <!-- Movimientos -->  <div class='bg-card rounded-[var(--radius-lg)] p-4 shadow-[var(--color-shadow)]'>    <div class='flex items-center gap-2 font-extrabold text-primary mb-3'>      <Icono nombre='history' size={18} />      Movimientos recientes    </div>    {#if movsPaginados.length === 0}      <div class='text-center text-muted py-6 text-sm'>Sin movimientos</div>    {:else}      {#each movsPaginados as mv}        <div class='flex justify-between items-center gap-2 py-2.5 border-b border-border {esCerrado(mv.fecha) ? 'opacity-60' : ''}'>          <div class='min-w-0 flex-1'>            <div class='font-bold text-sm'>{mv.concepto}</div>            <div class='text-xs text-muted'>{fmtFH(mv.fecha)}</div>          </div>          <div class='flex items-center gap-1 flex-shrink-0'>            {#if esCerrado(mv.fecha)}              <span class='inline-block px-2 py-0.5 rounded-full text-[0.6rem] font-extrabold text-white bg-warning' title='Periodo cerrado'>CERRADO</span>            {:else}              <b class='{mv.tipo === 'ingreso' ? 'text-success' : 'text-danger'}'>{mv.tipo === 'ingreso' ? '+' : '-'}{fmt(mv.monto)}</b>            {/if}          </div>        </div>      {/each}      {#if totalPaginasMovs > 1}        <div class='flex justify-center items-center gap-2 mt-3 text-sm'>          <button class='px-3 py-1 rounded-md border border-border bg-card disabled:opacity-30' onclick={() => paginaMovs--} disabled={paginaMovs <= 1}>←</button>          <span class='text-muted'>{paginaMovs} / {totalPaginasMovs}</span>          <button class='px-3 py-1 rounded-md border border-border bg-card disabled:opacity-30' onclick={() => paginaMovs++} disabled={paginaMovs >= totalPaginasMovs}>→</button>        </div>      {/if}    {/if}  </div></div>